  "Available:": { ru: "Доступно:", es: "Disponibles:", fr: "Disponibles :", ar: "المتاح:" },
  "No unassigned chats.": { ru: "Нет нераспределённых чатов.", es: "No hay chats sin asignar.", fr: "Aucun chat non assigné.", ar: "لا توجد محادثات غير معينة." },
