  "No chats in this project yet.": { ru: "В этом проекте пока нет чатов.", es: "Aún no hay chats en este proyecto.", fr: "Aucun chat dans ce projet pour l'instant.", ar: "لا توجد محادثات في هذا المشروع بعد." },
  "Remove from project": { ru: "Убрать из проекта", es: "Quitar del proyecto", fr: "Retirer du projet", ar: "إزالة من المشروع" },
  "Artifacts created in this project's chats will appear here.": { ru: "Здесь появятся артефакты, созданные в чатах этого проекта.", es: "Aquí aparecerán los artefactos creados en los chats de este proyecto.", fr: "Les artefacts créés dans les chats de ce projet apparaîtront ici.", ar: "ستظهر هنا العناصر المُنشأة في محادثات هذا المشروع." },
  "Flow files in project": { ru: "Файлы Flow в проекте", es: "Archivos Flow en el proyecto", fr: "Fichiers Flow du projet", ar: "ملفات Flow في المشروع" },
  "Files created by the Flow agent for this project will appear here.": { ru: "Здесь появятся файлы, созданные агентом Flow для этого проекта.", es: "Aquí aparecerán los archivos creados por el agente Flow para este proyecto.", fr: "Les fichiers créés par l'agent Flow pour ce projet apparaîtront ici.", ar: "ستظهر هنا الملفات التي أنشأها وكيل Flow لهذا المشروع." },
